    // and improves memory bandwidth utilization when M is reasonably large.
    Target t = get_jit_target_from_environment();
    const int vec = t.natural_vector_size<num_t>();

    init_data
        .vectorize(j, vec)   // contiguous in x == j
        .parallel(i);        // parallel over rows

