    // Original C:
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //       mean[j] += data[i][j];
    //   mean[j] /= float_n;
    //
    // Here we keep the same algebraic form as the original Halide version
    // (division inside the reduction) to preserve its numerical behaviour:
    //   mean[j] = sum_i (data[i][j] / float_n).
    Func mean("mean");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(Expr(0.0));

        mean(j) = zero;
        mean(j) += data_param(j, r_mean) / float_n_param;
    }

