    //
    // We now add an explicit schedule to improve performance while keeping
    // the *algorithmic* definitions above unchanged. All transformations
    // below only change loop ordering / tiling / parallelism.

    // Mean and variance are independent across columns j, so we can
    // parallelize across j. The reductions are over the row index only.
    mean.compute_root();
    mean.update()
        .parallel(j);

    var.compute_root();
    var.update()
        .parallel(j);

    // stddev is a pure per-column computation; parallelize across j.
    stddev.compute_root()
          .parallel(j);

