    // -------------------------------------------------------------------------
    // Column-wise variance and standard deviation:
    //
    // Original C:
    //   stddev[j] = 0;
    //   for (i) stddev[j] += (data[i][j] - mean[j])^2;
    //   stddev[j] /= float_n;
    //   stddev[j] = sqrt(stddev[j]);
    //   stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    //
    // We compute:
    //   var_sum[j] = sum_i (data[i][j] - mean[j])^2
    //   variance[j] = var_sum[j] / float_n
    //   sigma[j] = sqrt(variance[j])
    //   stddev[j] = (sigma[j] <= eps) ? 1.0 : sigma[j];
    //
    // This matches the original semantics but avoids dividing inside
    // the reduction loop.
    // -------------------------------------------------------------------------

    Func var_sum("var_sum");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(Expr(0.0));

        var_sum(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var_sum(j) += diff * diff;
    }

    Func variance("variance");
    {
        variance(j) = var_sum(j) / float_n_param;
    }

    Func stddev("stddev");
    {
        Expr eps = cast<num_t>(Expr(0.1));  // SCALAR_VAL(0.1)
        Expr one = cast<num_t>(Expr(1.0));
        Expr sigma = sqrt(variance(j));
        stddev(j) = select(sigma <= eps, one, sigma);
    }

    // -------------------------------------------------------------------------
    // Precompute normalization factors per column to turn divisions into
    // multiplications:
    //
    //   norm_factor[j] = sqrt(float_n) * stddev[j]
    //   inv_norm[j]    = 1 / norm_factor[j]
    //
    // Then normalized(j, i) = (data[i][j] - mean[j]) * inv_norm[j].
    // -------------------------------------------------------------------------

    Func norm_factor("norm_factor"), inv_norm("inv_norm");
    {
        Expr sqrt_n = sqrt(float_n_param);
        Expr one    = cast<num_t>(Expr(1.0));

        norm_factor(j) = sqrt_n * stddev(j);
        inv_norm(j)    = one / norm_factor(j);
    }

    // -------------------------------------------------------------------------
    // Center and reduce the column vectors:
    //
    // Original C:
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < M; j++) {
    //       data[i][j] -= mean[j];
    //       data[i][j] /= sqrt(float_n) * stddev[j];
    //     }
    //
    // We compute a new Func `normalized(j, i)` instead of modifying `data`:
    //   normalized(j, i) = (data[i][j] - mean[j]) * inv_norm[j]
    // -------------------------------------------------------------------------

    Func normalized("normalized");
    {
        normalized(j, i) = (data_param(j, i) - mean(j)) * inv_norm(j);
    }

    // -------------------------------------------------------------------------
    // Correlation matrix:
    //
    // Original C:
    //   for (i = 0; i < M-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < M; j++) {
    //       corr[i][j] = 0.0;
    //       for (k = 0; k < N; k++)
    //         corr[i][j] += data[k][i] * data[k][j];
    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[M-1][M-1] = 1.0;
    //
    // Using normalized data, the off-diagonals are dot products of
    // normalized columns. We compute the full symmetric matrix and then
    // explicitly set the diagonal to 1.0 to match the original semantics:
    //
    //   corr_base(q, p) = sum_k normalized(q, k) * normalized(p, k)
    //   corr(q, p)      = (p == q) ? 1.0 : corr_base(q, p)
    //
    // In buffer layout, corr_buf(q, p) corresponds to C corr[p][q].
    // -------------------------------------------------------------------------

    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(Expr(0.0));

        corr_base(q, p) = zero;
        corr_base(q, p) += normalized(q, r_k) * normalized(p, r_k);
    }

    Func corr("corr");
    {
        Expr one = cast<num_t>(Expr(1.0));
        corr(q, p) = select(p == q, one, corr_base(q, p));
    }

    // -------------------------------------------------------------------------
    // Scheduling
    // -------------------------------------------------------------------------

    // 1D reductions over columns: mean_sum, var_sum.
    // We parallelize and vectorize over j (columns). Each column is independent.
    mean_sum
        .compute_root()
        .parallel(j)
        .vectorize(j, vec);

    mean
        .compute_root()
        .parallel(j)
        .vectorize(j, vec);

    var_sum
        .compute_root()
        .parallel(j)
        .vectorize(j, vec);

    variance
        .compute_root()
        .parallel(j)
        .vectorize(j, vec);

    stddev
        .compute_root()
        .parallel(j)
        .vectorize(j, vec);

    norm_factor
        .compute_root()
        .parallel(j)
        .vectorize(j, vec);

    inv_norm
        .compute_root()
        .parallel(j)
        .vectorize(j, vec);

    // Normalized data is a dense N x M array.
    // Layout: x = j (columns), y = i (rows). We vectorize across columns and
    // parallelize across rows to get good cache behavior: each thread walks
    // along rows, and inner loops access contiguous memory.
    normalized
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // Correlation base is a reduction over k for each pair (q, p).
    // We tile (q, p) into 2D tiles, fuse the outer tile indices into a single
    // parallel dimension (to avoid nested parallelism), and vectorize across q
    // inside each tile. This improves locality and parallel utilization.
    Var qo("qo"), po("po"), qi("qi"), pi("pi"), tile_index("tile_index");

    const int tile_q = 16;
    const int tile_p = 16;

    corr_base
        .compute_root()
        .tile(q, p, qo, po, qi, pi, tile_q, tile_p)
        .fuse(qo, po, tile_index)
        .parallel(tile_index)
        .vectorize(qi, vec);

    // Final corr is cheap (just a select + load), so we simply compute it at root,
    // parallelized and vectorized across columns.
    corr
        .compute_root()
        .parallel(p)
        .vectorize(q, vec);

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline for the chosen target.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
