    // Column-wise mean: mean[j]
    //
    // Original C:
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //       mean[j] += data[i][j];
    //   mean[j] /= float_n;
    //
    // We first accumulate the sum, then divide once per column to
    // avoid doing a division in the inner loop.
    // -------------------------------------------------------------------------
    Func mean("mean");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(Expr(0.0));

        // Pure definition: initialize sum to zero.
        mean(j) = zero;

        // First update: accumulate the column sum.
        mean(j) += data_param(j, r_mean);

        // Second update: normalize by float_n (one division per column).
        mean(j) /= float_n_param;
    }

