    // Center and reduce the column vectors:
    //
    // Original C in-place:
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < M; j++) {
    //       data[i][j] -= mean[j];
    //       data[i][j] /= sqrt(float_n) * stddev[j];
    //     }
    //
    // We instead define a pure Func:
    //
    //   normalized(j, i) =
    //     (data[i][j] - mean[j]) * inv_std[j]
    //
