    // Correlation matrix (base):
    //
    // Using normalized data, the off-diagonals are dot products of
    // normalized columns:
    //
    //   corr_base[p][q] = sum_k normalized[k][p] * normalized[k][q]
    //
    // In Halide layout corr_base(q, p) corresponds to corr[p][q].
    // -------------------------------------------------------------------------
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(Expr(0.0));

        corr_base(q, p) = zero;
        corr_base(q, p) += normalized(q, r_k) * normalized(p, r_k);
    }

