    // Final correlation matrix with unit diagonal:
    //
    // Original C:
    //   for (i = 0; i < M-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < M; j++) {
    //       corr[i][j] = 0.0;
    //       for (k = 0; k < N; k++)
    //         corr[i][j] += data[k][i] * data[k][j];
    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[M-1][M-1] = 1.0;
    //
    // We compute the full symmetric matrix via corr_base, then
    // override the diagonal with 1.0 to match the original semantics:
    //
    //   corr[p][q] = (p == q) ? 1.0 : corr_base[p][q];
    //
    // Halide layout: corr(q, p) corresponds to corr[p][q] in C.
    // -------------------------------------------------------------------------
    Func corr("corr");
