    // and double. Halide will automatically handle tails.
    // -------------------------------------------------------------------------
    const int vec_width = 8;  // reasonable default for modern x86/ARM

    // mean: two update steps (accumulation + final division).
    mean.compute_root();
    mean.parallel(j).vectorize(j, vec_width);
    mean.update(0).parallel(j).vectorize(j, vec_width);
    mean.update(1).parallel(j).vectorize(j, vec_width);

